import { NextResponse } from 'next/server';
import { exec } from 'child_process';
import { promisify } from 'util';
import { writeFile, readFile, unlink, mkdir } from 'fs/promises';
import path from 'path';
import os from 'os';

const execPromise = promisify(exec);

export async function POST(request) {
    let tempDir = '';

    try {
        const formData = await request.formData();
        const file = formData.get('file');

        if (!file) {
            return NextResponse.json({ error: "No se subió ningún archivo" }, { status: 400 });
        }

        // 1. Crear directorio temporal
        tempDir = path.join(os.tmpdir(), `logisparse_${Date.now()}`);
        await mkdir(tempDir, { recursive: true });

        // 2. Guardar PDF temporal
        const arrayBuffer = await file.arrayBuffer();
        const buffer = Buffer.from(arrayBuffer);
        const pdfPath = path.join(tempDir, 'factura.pdf');
        await writeFile(pdfPath, buffer);

        // 3. Ejecutar tu script de Python
        const scriptPath = path.join(process.cwd(), 'scripts', 'procesar_factura.py');
        const pythonCmd = process.platform === 'win32' ? 'python' : 'python3';

        await execPromise(`"${pythonCmd}" "${scriptPath}" "${pdfPath}" "${tempDir}"`);

        // 4. LEER EL ARCHIVO CSV QUE YA GENERA TU SCRIPT
        const csvPath = path.join(tempDir, 'factura_items.csv');
        const csvBuffer = await readFile(csvPath);

        // 5. Limpieza
        await unlink(pdfPath).catch(() => {});
        await unlink(csvPath).catch(() => {});
        await unlink(path.join(tempDir, 'factura_tabulada.xlsx')).catch(() => {});

        // 6. Retornar el CSV como archivo de descarga
        const nombreSalida = file.name.replace(/\.[^/.]+$/, "") + '_bd.csv';

        return new NextResponse(csvBuffer, {
            status: 200,
            headers: {
                'Content-Type': 'text/csv; charset=utf-8',
                'Content-Disposition': `attachment; filename="${nombreSalida}"`,
            },
        });

    } catch (error) {
        console.error("[ERROR] Fallo al procesar la factura:", error);
        return NextResponse.json(
            { error: "Fallo en la extracción del CSV", detalles: error.message },
            { status: 500 }
        );
    }
}